   if(!incoming.days[now])incoming.days[now]={tasks:{},water:0};
   try{localStorage.setItem(STORE,JSON.stringify(incoming))}
   catch{toast('Restore failed: device storage is unavailable or full. Your journal was not replaced.');return}
