function renderStreak(){const monthKey=keyFor(month).slice(0,7),title=month.toLocaleDateString('en-GB',{month:'long',year:'numeric'}),first=(month.getDay()+6)%7,days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();const run=streaks(),all=Object.keys(state.days).map(summary),totalXP=all.reduce((n,s)=>n+s.xp,0);const stats={xp:totalXP,max:Math.max(1,all.reduce((n,s)=>n+s.max,0))};const records=Object.keys(state.days).filter(k=>k.startsWith(monthKey));const active=records.filter(qualifies).length;const weekStart=offsetDay(selected,-((dateFrom(selected).getDay()+6)%7)),weekEnd=offsetDay(weekStart,6),weekRecords=Object.keys(state.days).filter(k=>k>=weekStart&&k<=weekEnd&&k<=today),weekAvg=weekRecords.length?Math.round(weekRecords.reduce((n,k)=>n+(xpPercent(k)||0),0)/weekRecords.length):null;
 let cells=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')+'<span></span>'.repeat(first);
 for(let n=1;n<=days;n++){const k=monthKey+'-'+String(n).padStart(2,'0'),s=summary(k),p=xpPercent(k)||0,level=p>0?Math.max(1,Math.ceil(p/25)):0;cells+=`<button class="day-cell level-${level} ${k===today?'today':''} ${k===selected?'selected':''} ${k>today?'future':''}" data-calendar="${k}" aria-label="${dateFrom(k).toLocaleDateString('en-GB',{day:'numeric',month:'long'})}, ${state.days[k]?`${signedXP(s.xp)} of ${fmt(s.max)} XP`:'no record'}" title="${n} ${title} · ${fmt(p)}% XP" aria-pressed="${k===selected}" ${k>today?'disabled':''}>${n}</button>`}
 main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">History</div><h1>Your consistency.</h1></div></div>${statsHtml(stats,true)}<div class="content-grid streak-layout"><section class="task-column"><div class="month-card"><div class="month-heading"><h2>${title}</h2><div class="month-controls"><button class="icon-button" id="prev-month" aria-label="Previous month">${svg('left')}</button><button class="icon-button" id="next-month" aria-label="Next month" ${monthKey>=today.slice(0,7)?'disabled':''}>${svg('right')}</button></div></div><div class="calendar">${cells}</div><div class="legend"><span>Tap a day to view</span><span class="legend-scale">Less ${[0,1,2,3,4].map(n=>`<i class="legend-square level-${n}"></i>`).join('')} More</span></div></div><section class="history-area"><div class="section-head"><h2>${selected===today?'Today':selected===offsetDay(today,-1)?'Yesterday':dateFrom(selected).toLocaleDateString('en-GB',{day:'numeric',month:'long'})}</h2><span class="subtle">${state.days[selected]?`${fmt(summary(selected).xp)} / ${fmt(summary(selected).max)} XP`:'No recorded activity'}</span></div>${dayEditorHtml(selected)}</section></section><aside class="streak-aside"><div class="small-metric"><div class="eyebrow">Days you showed up</div><strong>${active}<span style="color:#727272;font-size:25px"> / ${days}</span></strong><p>80% XP · this month</p></div><div class="small-metric"><div class="eyebrow">Weekly XP</div><strong>${weekAvg??'—'}<span style="color:#727272;font-size:25px">%</span></strong><p>${dateFrom(weekStart).toLocaleDateString('en-GB',{day:'numeric',month:'short'})} – ${dateFrom(weekEnd).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</p></div></aside></div>`;
}
function bindContent(){document.querySelector('[data-open-map]')?.addEventListener('click',showDailyGlance);document.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>editExam(Number(b.dataset.exam)));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.day,b.dataset.task));document.querySelectorAll('[data-water]').forEach(b=>b.onclick=()=>{if(b.dataset.day!==today)return;const d=ensureDay(b.dataset.day),n=Number(b.dataset.water);d.water=d.water===n?n-1:n;save();render();animateElement(document.querySelector('[data-water="'+n+'"]'),[{transform:'scale(.94)'},{transform:'scale(1)'}]);toast(`${d.water} / 4 litres recorded`)});document.querySelectorAll('[data-water-extra]').forEach(b=>b.onclick=()=>showWaterMeter(b.dataset.day));document.querySelectorAll('[data-calendar]').forEach(b=>b.onclick=()=>{selected=b.dataset.calendar;render()});document.getElementById('prev-month')?.addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);selected=keyFor(month);render()});document.getElementById('next-month')?.addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);selected=keyFor(month).slice(0,7)===today.slice(0,7)?today:keyFor(month);render()})}
function showModal(content){document.getElementById('modal-content').innerHTML=content;modal.showModal();modal.querySelector('[data-close]')?.addEventListener('click',()=>modal.close())}
function modalHeader(eyebrow,title){return `<div class="modal-heading"><div><div class="eyebrow">${eyebrow}</div><h2 id="dialog-title">${title}</h2></div><button class="icon-button" data-close aria-label="Close dialog">${svg('close')}</button></div>`}
function showWaterMeter(k){if(k!==today){toast('Check-ins are limited to today.');return}const d=ensureDay(k);let bonus=Math.max(0,Math.min(3,(d.water||0)-3));showModal(`${modalHeader('Hydration','Extra water')}<div class="water-meter-sheet"><div class="big-water-drop" id="big-water-drop" role="slider" tabindex="0" aria-label="Add extra water" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${bonus}"><svg viewBox="0 0 120 160" aria-hidden="true"><defs><clipPath id="water-drop-clip"><path d="M60 4C38 34 16 61 16 96a44 44 0 0 0 88 0C104 61 82 34 60 4Z"/></clipPath></defs><path class="drop-shadow" d="M60 4C38 34 16 61 16 96a44 44 0 0 0 88 0C104 61 82 34 60 4Z"/><rect id="water-fill" clip-path="url(#water-drop-clip)" x="0" y="160" width="120" height="0"/></svg><b id="water-bonus-label">+${fmt(bonus)}</b></div></div><button class="primary-button" id="confirm-water">Save hydration</button>`);const drop=document.getElementById('big-water-drop'),fill=document.getElementById('water-fill'),label=document.getElementById('water-bonus-label');const paint=()=>{const pct=bonus/3,y=160-(pct*156);fill.setAttribute('y',String(y));fill.setAttribute('height',String(160-y));label.textContent='+'+fmt(bonus);drop.setAttribute('aria-valuenow',String(bonus))};const setFromY=clientY=>{const r=drop.getBoundingClientRect(),pct=Math.max(0,Math.min(1,(r.bottom-clientY)/r.height));bonus=Math.round(pct*3);paint()};drop.onpointerdown=e=>{drop.setPointerCapture?.(e.pointerId);setFromY(e.clientY);drop.onpointermove=move=>setFromY(move.clientY);drop.onpointerup=drop.onpointercancel=()=>{drop.onpointermove=null}};drop.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowRight'){bonus=Math.min(3,bonus+1);paint();e.preventDefault()}else if(e.key==='ArrowDown'||e.key==='ArrowLeft'){bonus=Math.max(0,bonus-1);paint();e.preventDefault()}};paint();document.getElementById('confirm-water').onclick=()=>{d.water=3+bonus;save();modal.close();render();toast(`${d.water} / 4 litres recorded`)}}
function openTask(k,id){if(k!==today){toast('Check-ins are limited to today.');return}const t=schedule(k).find(x=>x.id===id),e=entry(k,t),done=e?.status==='done';if(t.type==='simple'&&!e){ensureDay(k).tasks[id]={status:'done',rating:100};save();render();animateCheck(id);toast(t.max?`+${t.max} XP · A promise kept`:'Swimming complete');return}
 if(t.type==='focus'){const initial=e?.rating??75;showModal(`${modalHeader('A moment of reflection',t.name)}<div class="productivity-value"><span id="rating-number">${initial}</span><small>%</small></div><div class="xp-preview" id="xp-preview">+${fmt(t.max*initial/100)} of ${t.max} XP</div><input type="range" id="rating" aria-label="Session productivity" min="0" max="100" step="1" value="${initial}"><div class="range-labels"><span>A distracted day</span><span>Fully present</span></div><button class="primary-button" id="confirm-task">${done?'Update check-in':'Save my check-in'}</button><button class="secondary-button" id="miss-task">Mark missed · −${t.penalty} XP</button>${e?'<button class="secondary-button" id="undo-task">Clear check-in</button>':''}`);
 const r=document.getElementById('rating');r.oninput=()=>{document.getElementById('rating-number').textContent=r.value;document.getElementById('xp-preview').textContent=`+${fmt(t.max*r.value/100)} of ${t.max} XP`};document.getElementById('confirm-task').onclick=()=>recordTask(k,t,{status:'done',rating:Number(r.value)});
 }else if(t.type==='class'){const values=e?.subjects||[75,75,75];showModal(`${modalHeader('Classroom reflection','Make learning count.')}${['Physics','Mathematics','Chemistry'].map((name,i)=>`<div class="class-row"><div class="class-label"><label for="subject-${i}">${name}</label><span id="subject-value-${i}">${values[i]}%</span></div><input id="subject-${i}" class="subject-range" type="range" min="0" max="100" value="${values[i]}" aria-label="${name} productivity"></div>`).join('')}<div class="xp-preview" id="class-xp"></div><button class="primary-button" id="confirm-task">Save my check-in</button><button class="secondary-button" id="miss-task">Mark missed · 0 XP</button>${e?'<button class="secondary-button" id="undo-task">Clear check-in</button>':''}`);const ranges=[...document.querySelectorAll('.subject-range')];const update=()=>{ranges.forEach((r,i)=>document.getElementById('subject-value-'+i).textContent=r.value+'%');document.getElementById('class-xp').textContent='+'+fmt(ranges.reduce((sum,r,i)=>sum+Number(r.value)*[.33,.33,.34][i],0))+' of 100 XP'};ranges.forEach(r=>r.oninput=update);update();document.getElementById('confirm-task').onclick=()=>{const subjects=ranges.map(r=>Number(r.value));recordTask(k,t,{status:'done',subjects,rating:subjects.reduce((s,v,i)=>s+v*[.33,.33,.34][i],0)})};
 }else{showModal(`${modalHeader('Endurance',t.name)}<button class="primary-button" id="confirm-task">${done?'Keep completed':'Mark complete'}${t.max?' · +'+t.max+' XP':''}</button><button class="secondary-button" id="miss-task">Mark missed · −${fmt(t.penalty)} XP</button>${e?'<button class="secondary-button" id="undo-task">Clear check-in</button>':''}`);document.getElementById('confirm-task').onclick=()=>recordTask(k,t,{status:'done',rating:100})}
 document.getElementById('miss-task').onclick=()=>recordTask(k,t,{status:'missed',rating:0});document.getElementById('undo-task')?.addEventListener('click',()=>{if(k!==today){modal.close();return}delete ensureDay(k).tasks[id];save();modal.close();render();animateCheck(id);toast('Check-in cleared')});}
function recordTask(k,t,data){if(k!==today){modal.close();checkDate();toast('Check-ins are limited to today.');return}ensureDay(k).tasks[t.id]=data;save();modal.close();render();animateCheck(t.id);const xp=taskXP(t,data);toast(`${xp>0?'+':''}${fmt(xp)} XP · Check-in saved`)}
function showRules(){showModal(`${modalHeader('The details','Your rhythm, explained.')}<ul class="rule-list"><li><strong>Focus XP:</strong> productivity ÷ 100 × the session reward. A 75% session worth 200 XP earns 150 XP.</li><li><strong>Daily productivity:</strong> the average of each XP-bearing ritual’s completion percentage plus hydration. Incomplete rituals count as 0%; class focus uses 33/33/34 subject weights.</li><li><strong>Streaks:</strong> a day counts at 80% of its maximum XP, after penalties and including hydration.</li><li><strong>Missed rituals:</strong> unfinished rituals on recorded past days receive their listed penalty. Today’s pending rituals are not penalised yet. Unrecorded days never create XP debt.</li><li><strong>Your schedule:</strong> the second wake-up is treated as 15:20. Evening sessions finish at midnight. Days close at midnight IST. Check-ins are limited to today; History is read-only.</li><li><strong>Weekends:</strong> classes become two 400 XP sessions, 08:00–11:00 and 11:30–14:00.</li><li><strong>Fridays:</strong> swimming takes 17:30–19:00. The adjacent focus sessions shorten to fit. Swimming has no XP reward or penalty.</li><li><strong>Water:</strong> your requested target is 4 litres. Tap a droplet to set the total; tap the selected total again to subtract a litre.</li><li><strong>Your data:</strong> saved in this browser on this device. Export a JSON backup to keep a copy or transfer it to another device. Import restores the full journal, including history.</li></ul><button class="primary-button" data-close-bottom>Back to my practice</button>`);modal.querySelector('[data-close-bottom]').onclick=()=>modal.close()}

